/* Types */
/**
 *  Accesionar una orden: crea una muestra (tubo) de un tipo determinado
 *  ligada a la orden. Se puede llamar varias veces (un tubo por tipo).
 */
export type AccessionOrderInput = {
	orderId: number,
	sampleTypeId: number,
	/**  YYYY-MM-DD HH:MM:SS (por defecto ahora si se omite). */
	receivedAt: string | null,
	collectedBy: string | null,
	notes: string | null,
};

export type AddVisitAttachmentInput = {
	visitId: number,
	/**  BEFORE | AFTER | DOCUMENT */
	kind: string | null,
};

export type AddVisitServiceInput = {
	serviceId: number,
	/**  Profesional asignado a esta línea. */
	professionalId: number | null,
	quantity: number,
	notes: string | null,
};

export type Analyte = {
	id: number,
	code: string,
	name: string,
	unit: string | null,
	method: string | null,
};

/**  Conteo de un analito (para el ranking de los más solicitados). */
export type AnalyteCount = {
	analyteName: string,
	count: number,
};

/**
 *  Equipo analizador de laboratorio (marca/modelo). El perfil GENERAL (ID 1)
 *  agrupa los rangos estándar por especie/sexo/edad sin equipo automatizado.
 */
export type Analyzer = {
	id: number,
	code: string,
	name: string,
	manufacturer: string | null,
	model: string | null,
	isActive: boolean,
	notes: string | null,
	/**  Nº de rangos de referencia configurados para este equipo. */
	rangeCount: number,
};

/**  Entrada de la cola de importación automática (un archivo detectado). */
export type AnalyzerImportJob = {
	id: number,
	sourceId: number,
	analyzerId: number,
	analyzerName: string,
	fileName: string,
	/**  IMPORTADO | FALLIDO */
	status: string,
	samplesUpdated: number,
	resultsImported: number,
	skippedRows: number,
	errorMsg: string | null,
	/**  YYYY-MM-DD HH:MM:SS */
	processedAt: string,
};

/**  Mapeo confirmado por el usuario para la importación. */
export type AnalyzerImportMapping = {
	/**  Índice (0-based) de la columna con el código de la muestra. */
	sampleCodeColumn: number,
	/**  Mapeos columna → analito. */
	columns: ImportColumnMapping[],
};

/**
 *  Fuente automática de resultados configurada para un analizador.
 *  Hoy el único driver es la carpeta vigilada (CSV); el campo `source_type`
 *  queda listo para drivers futuros (ASTM serial, HL7 por red…).
 */
export type AnalyzerSource = {
	id: number,
	analyzerId: number,
	analyzerName: string,
	sourceType: string,
	folderPath: string | null,
	enabled: boolean,
	/**  Última vez que el supervisor sondeó esta fuente (YYYY-MM-DD HH:MM:SS). */
	lastPollAt: string | null,
	/**  Mapeo CSV guardado (columna del código de muestra + columnas analito). */
	mapping: AnalyzerImportMapping | null,
	/**  Nº de analitos mapeados (atajo para la lista). */
	mappedColumns: number,
};

/**  Error tipado de la app. Se serializa como `{ type, data }` para el frontend. */
export type AppError = { type: "Db"; data: string } | { type: "NotFound"; data: string } | { type: "Validation"; data: string } | { type: "Forbidden"; data: string } | { type: "Internal"; data: string };

/**  Cita de la agenda generalizada (cualquier servicio del catálogo). */
